import sys

DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"


def to_base(n, base):
    out = ""
    while n > 0:
        out = DIGITS[n % base] + out
        n //= base
    return out


def is_valid_number(number_str, base):
    if not number_str or not number_str[0].isalpha and (number_str[0] == '-' or number_str[0] == '+'):
        return False
    if number_str[0] == '-':
        number_str = number_str[1:]
    for ch in number_str:
        if ch not in DIGITS:
            return False
    try:
        value = int(number_str, base)
    except ValueError:
        return False
    return True


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 3:
            print("ERROR")
            continue
        number, src, dst = parts
        src, dst = int(src), int(dst)
        if not (2 <= src <= 36 and 2 <= dst <= 36):
            print("ERROR")
            continue
        if not is_valid_number(number, src):
            print("ERROR")
            continue
        try:
            value = int(number, src)
        except ValueError:
            print("ERROR")
            continue
        result = to_base(value, dst)
        print(result)


if __name__ == "__main__":
    main()
